import networkx as nx

def check_graph(n, edges):
    G = nx.Graph()
    G.add_nodes_from(range(n))
    G.add_edges_from(edges)

    # Check minimum degree
    min_degree = min(dict(G.degree()).values())

    # Check clique number
    clique_number = nx.graph_clique_number(G)

    # Check chromatic number
    chromatic_number = nx.coloring.greedy_color(G, strategy='largest_first')
    # Note: greedy_color is an approximation, but for small graphs it might be exact.
    # Let's use a more robust method for chromatic number.
    # Actually, for small graphs, we can use nx.coloring.greedy_color and check if it's <= 5.
    # Or better, use a backtracking algorithm.

    # For small graphs, we can use a simple coloring check.
    def is_k_colorable(G, k):
        coloring = {}
        def solve(node):
            if node == n:
                return True
            for color in range(k):
                if all(coloring.get(neighbor) != color for neighbor in G.neighbors(node)):
                    coloring[node] = color
                    if solve(node + 1):
                        return True
                    del coloring[node]
            return False
        return solve(0)

    return min_degree, clique_number, is_k_colorable(G, 5)

