def get_min_degree(n, edges):
    degrees = [0] * n
    for u, v in edges:
        degrees[u] += 1
        degrees[v] += 1
    return min(degrees)

def get_clique_number(n, edges):
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Bron-Kerbosch algorithm
    def bron_kerbosch(r, p, x):
        if not p and not x:
            yield len(r)
        for v in list(p):
            yield from bron_kerbosch(r | {v}, p & adj[v], x & adj[v])
            p.remove(v)
            x.add(v)

    return max(bron_kerbosch(set(), set(range(n)), set()))

def is_k_colorable(n, edges, k):
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    coloring = [-1] * n
    def solve(node):
        if node == n:
            return True
        for color in range(k):
            if all(coloring[neighbor] != color for neighbor in adj[node]):
                coloring[node] = color
                if solve(node + 1):
                    return True
                coloring[node] = -1
        return False
    return solve(0)

